import{z as n,x as p,o as E,c as B,q as A,j as o,D as r,d as e,s as l,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"HAMT","description":"","frontmatter":{"title":"HAMT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hamt.md","filePath":"cs/hamt.md","lastUpdated":1791063341000}'),d={name:"cs/hamt.md"};function m(c,a,h,T,u,D){const s=p("Mermaid");return E(),B("div",null,[a[2]||(a[2]=A('<h1 id="hamt" tabindex="-1">HAMT <a class="header-anchor" href="#hamt" aria-label="Permalink to &quot;HAMT&quot;">​</a></h1><div class="epigraph"><p>用哈希的若干比特当路径，节点用位图压缩孩子数组；持久更新只复制路径，未改的分支共享。</p><footer>—— 据 Bagwell, Ideal Hash Trees, 2001；Okasaki, Purely Functional Data Structures 整理</footer></div><p><a href="/cs/rope-structure">上一课</a> 按位置分裂。<a href="/cs/trie">Trie</a> 按键字符，哈希键则路径均匀。<a href="/cs/persistent-segment-tree">可持久化线段树</a> 的路径复制在此换成哈希前缀。本课不拼接字符串。缺口是 Hash Array Mapped Trie：函数式字典的主流表示（Clojure、Scala 等）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持久 <code>map</code>：每次插入若拷全表 \\(\\Theta(n)\\)。HAMT：哈希 \\(h(k)\\) 从高到低每次取 \\(b\\) 比特（常 5，扇出 32）。节点：<code>bitmap</code> 标明哪些槽非空，<code>array</code> 只存存在的孩子，popcount 算下标。冲突：最终叶子链或再哈希。缺口是<strong>用位图压缩稀疏的 \\(2^b\\) 叉 trie</strong>，使内部节点小、路径 \\(O(w/b)\\)。</p><p><span class="marginnote">数字实例：32 位哈希、每层吃 5 比特，扇出 \\(2^5=32\\)，树高最多 \\(32\\div5\\approx7\\) 层。一个 32 槽节点若只有 3 个孩子，bitmap 就是 3 个 1、数组只分配 3 项——这就是「位图压缩稀疏数组」省下的空间。</span></p><p><span class="marginnote">术语翻译：popcount（population count）是「数一个二进制数里有几个 1」的硬件指令。HAMT 拿它做下标换算：bitmap 中目标比特之前有几个 1，孩子就存在数组的第几格。</span></p><p><span class="marginnote">直觉类比：路径复制像 Git 提交——新版本只复制被改动的目录链，其余文件全是共享的旧引用。所以「每次更新都要拷一份字典」的担心不成立，代价只是根到叶那一条路径。</span></p><p><span class="marginnote">Bagwell 2001 技术报告 <em>Ideal Hash Trees</em>。Okasaki 讨论持久树共享。本课不把 JVM 实现细节当理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：沿比特选孩子，位图测试该比特。插入：路径复制，改一个孩子槽；若叶冲突则加一层。删除对称，可收缩。并发：可与 CAS 根指针结合（后课），本课先单线程持久。</p>',11)),(E(),o(i,null,{default:r(()=>[l(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HK%5B%22h(k)%20%E7%9A%84%E6%AF%94%E7%89%B9%E5%9D%97%22%5D%20--%3E%20BM%5B%22%E8%8A%82%E7%82%B9%20bitmap%22%5D%0A%20%20BM%20--%3E%20IDX%5B%22popcount%20%E5%BE%97%E6%95%B0%E7%BB%84%E4%B8%8B%E6%A0%87%22%5D%0A%20%20IDX%20--%3E%20CH%5B%22%E5%AD%A9%E5%AD%90%3A%20%E5%AD%90%E8%8A%82%E7%82%B9%E6%88%96%E5%8F%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与链式哈希表：HAMT 保持久共享、无扩容抖动；常数通常更大。与 ART：下一课自适应基数树按真实键字节、面向内存数据库，节点类型可变。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("空间：节点只分配非空孩子。缓存：数组小而密，好于指针 256 叉。哈希仍要抗碰撞；HAMT 不消除"),t("a",{href:"/cs/hash-collision"},"散列碰撞"),e(" 语义，只是把链改成更深路径。")],-1)),(E(),o(i,null,{default:r(()=>[l(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E7%89%88%E6%9C%AC%E6%A0%B9%22%5D%20--%3E%20A%5B%22%E8%B7%AF%E5%BE%84%E8%8A%82%E7%82%B9%20A%22%5D%20--%3E%20LEAF%5B%22%E6%97%A7%E5%8F%B6%22%5D%0A%20%20NEW%5B%22%E6%8F%92%E5%85%A5%20k%EF%BC%9A%E4%BB%8E%E6%A0%B9%E5%88%B0%E5%8F%B6%E5%A4%8D%E5%88%B6%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20A2%5B%22%E6%96%B0%E8%8A%82%E7%82%B9%20A%E2%80%B2%EF%BC%88%E5%8F%AA%E6%94%B9%E4%B8%80%E4%B8%AA%E6%A7%BD%EF%BC%89%22%5D%20--%3E%20LEAF2%5B%22%E6%96%B0%E5%8F%B6%20k%22%5D%0A%20%20OLD%20-.%20%22%E6%9C%AA%E6%94%B9%E5%88%86%E6%94%AF%E7%85%A7%E6%97%A7%E5%85%B1%E4%BA%AB%22%20.-%20A2%0A%20%20LEAF%20-.%20%22%E5%85%B6%E4%BD%99%E5%AD%A9%E5%AD%90%E5%85%B1%E4%BA%AB%22%20.-%20A2%0A%20%20NEW%20--%3E%20ROOTMAP%5B%22%E6%96%B0%20map%20%E5%8F%AA%E6%8D%A2%E6%A0%B9%E6%8C%87%E9%92%88%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p>不要把 HAMT 当神经网络权重存储课——本栏是 CS 字典结构。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CHAMP 等全部变体。有序遍历不是 HAMT 强项（无序哈希）。按字节自适应扇出是 ART。</p><p>后课默认：持久无序映射可用 HAMT。内存有序/字节键高扇出用 ART。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HAMT：哈希比特 trie + 位图压缩数组，路径复制。</li><li>扇出常 32；持久共享未改分支。</li><li>下一课 ART 按键字节自适应节点。</li><li>出处：Bagwell, 2001；Okasaki。</li></ul>',6))])}const b=n(d,[["render",m]]);export{_ as __pageData,b as default};
